# Generated by Gemini 3.0
import pandas as pd
import matplotlib.pyplot as plt
import numpy as np
import os

def workload_distribution_visualizer(theta=0.99):
    script_dir = os.path.dirname(os.path.abspath(__file__))
    scv_filename = "distribution_test.csv"
    csv_file_path = os.path.join(script_dir, scv_filename)
    print(f"Reading {csv_file_path}...")
    df = pd.read_csv(csv_file_path)
    
    # 데이터 집계: 어떤 ID가 몇 번 나왔는지 카운트
    # generated_id 별 빈도수 계산
    counts = df['generated_id'].value_counts()
    
    # -------------------------------------------------------
    # Plot 1: Rank-Frequency Plot (Log-Log)
    # -------------------------------------------------------
    # Zipfian 법칙 검증의 표준: 로그 스케일에서 직선이어야 함
    plt.figure(figsize=(14, 6))
    
    plt.subplot(1, 2, 1)
    # counts.values는 이미 빈도수 내림차순 정렬되어 있음 (Rank 1, 2, 3...)
    ranks = np.arange(1, len(counts) + 1)
    frequencies = counts.values
    
    plt.loglog(ranks, frequencies, marker='.', linestyle='none', markersize=2,label=f'Approx. Zipfian Dist. (theta={theta})', alpha=0.5)
    plt.title("Rank vs Frequency (Log-Log)")
    plt.xlabel("Rank (log scale)")
    plt.ylabel("Frequency (log scale)")
    plt.grid(True, which="both", ls="-", alpha=0.2)
    
    # 이론적인 Zipfian 직선
    # y = C * x^(-theta)  => log(y) = -theta * log(x) + C
    if len(ranks) > 0:
        ref_x = ranks
        ref_y = frequencies[0] * (ref_x ** -theta)
        plt.loglog(ref_x, ref_y, 'r--', label=f'Theoretical Zipfian Dist. (theta={theta})', alpha=0.5)
        plt.legend()

    # -------------------------------------------------------
    # Plot 2: ID - Frequency Scatter (Scrambling Check)
    # -------------------------------------------------------
    # Scrambled라면 ID 0번에 핫스팟이 몰리면 안 되고, 전체적으로 퍼져 있어야 함
    plt.subplot(1, 2, 2)
    
    # ID별로 다시 정렬하지 않고, ID(x축) vs 빈도(y축) 그대로 찍음
    # counts.index는 ID, counts.values는 빈도
    plt.scatter(counts.index, counts.values, s=2, alpha=0.3, color='green')
    
    plt.title("Key ID vs Frequency (Scrambled)")
    plt.xlabel("Key ID")
    plt.ylabel("Frequency")
    plt.grid(True, alpha=0.2)
    
    # 상위 5개 핫스팟이 어디있는지 표시
    top_5 = counts.head(5)
    print("\n[Top 5 Hot Keys]")
    print(top_5)
    
    for id, freq in top_5.items():
        plt.annotate(f"ID:{id}", (id, freq), xytext=(id, freq*1.1), 
                     arrowprops=dict(facecolor='black', shrink=0.05), ha='center')

    plt.tight_layout()
    plt.show()

    output_path = os.path.join(script_dir, "zipfian_check.png")
    plt.savefig(output_path)
    print(f"Graph saved to: {output_path}")
    

if __name__ == "__main__":
    workload_distribution_visualizer(0.7)